/**
 * Safe Math Utilities for OGZPrime Trading System
 * @module SafeMathUtilities
 * @description Comprehensive mathematical operations with robust error handling
 */
class SafeMathUtilities {
  /**
   * Safely divide two numbers
   * @param {number} numerator - Number to be divided
   * @param {number} denominator - Number to divide by
   * @param {number} [defaultValue=0] - Default return value if division is invalid
   * @returns {number} Result of division or default value
   */
  static safeDivide(numerator, denominator, defaultValue = 0) {
    // Comprehensive division safety checks
    if (
      denominator === 0 || 
      !Number.isFinite(numerator) || 
      !Number.isFinite(denominator)
    ) {
      return defaultValue;
    }
    return numerator / denominator;
  }

  /**
   * Calculate percentage with safety checks
   * @param {number} part - Part of the whole
   * @param {number} whole - Total value
   * @param {number} [defaultValue=0] - Default return value
   * @returns {number} Percentage calculation
   */
  static safePercentage(part, whole, defaultValue = 0) {
    if (whole === 0 || !Number.isFinite(part) || !Number.isFinite(whole)) {
      return defaultValue;
    }
    return (part / whole) * 100;
  }

  /**
   * Calculate compound growth with robust error handling
   * @param {number} principal - Initial investment
   * @param {number} rate - Growth rate
   * @param {number} time - Time period
   * @returns {number} Compound growth result
   */
  static compoundGrowth(principal, rate, time) {
    if (
      !Number.isFinite(principal) || 
      !Number.isFinite(rate) || 
      !Number.isFinite(time)
    ) {
      return principal;
    }

    return principal * Math.pow(1 + rate, time);
  }

  /**
   * Calculate moving average with safety checks
   * @param {number[]} values - Array of numeric values
   * @param {number} [window] - Moving average window size
   * @returns {number} Moving average
   */
  static movingAverage(values, window) {
    if (!Array.isArray(values) || values.length === 0) {
      return 0;
    }

    // Use full array if no window specified
    const useWindow = window || values.length;
    const validValues = values
      .slice(-useWindow)
      .filter(val => Number.isFinite(val));

    if (validValues.length === 0) {
      return 0;
    }

    return validValues.reduce((sum, val) => sum + val, 0) / validValues.length;
  }

  /**
   * Calculate standard deviation with robust error handling
   * @param {number[]} values - Array of numeric values
   * @returns {number} Standard deviation
   */
  static standardDeviation(values) {
    if (!Array.isArray(values) || values.length === 0) {
      return 0;
    }

    const validValues = values.filter(val => Number.isFinite(val));

    if (validValues.length === 0) {
      return 0;
    }

    const mean = this.movingAverage(validValues);
    const squaredDiffs = validValues.map(val => Math.pow(val - mean, 2));

    return Math.sqrt(
      this.movingAverage(squaredDiffs)
    );
  }

  /**
   * Normalize values to a specific range
   * @param {number[]} values - Array of numeric values
   * @param {number} [min=0] - Minimum of target range
   * @param {number} [max=1] - Maximum of target range
   * @returns {number[]} Normalized values
   */
  static normalizeValues(values, min = 0, max = 1) {
    if (!Array.isArray(values) || values.length === 0) {
      return [];
    }

    const validValues = values.filter(val => Number.isFinite(val));

    if (validValues.length === 0) {
      return [];
    }

    const minVal = Math.min(...validValues);
    const maxVal = Math.max(...validValues);

    // Prevent division by zero
    if (minVal === maxVal) {
      return validValues.map(() => (min + max) / 2);
    }

    return validValues.map(val => 
      min + (val - minVal) * (max - min) / (maxVal - minVal)
    );
  }

  /**
   * Robust percentage change calculation
   * @param {number} oldValue - Original value
   * @param {number} newValue - New value
   * @returns {number} Percentage change
   */
  static percentageChange(oldValue, newValue) {
    if (!Number.isFinite(oldValue) || !Number.isFinite(newValue)) {
      return 0;
    }

    if (oldValue === 0) {
      return newValue !== 0 ? 100 : 0;
    }

    return ((newValue - oldValue) / Math.abs(oldValue)) * 100;
  }

  /**
   * Generate a cryptographically secure random number
   * @param {number} min - Minimum value
   * @param {number} max - Maximum value
   * @returns {number} Secure random number
   */
  static secureRandomNumber(min, max) {
    const range = max - min;
    const bytesNeeded = Math.ceil(Math.log2(range) / 8);
    const cutoff = Math.floor((256 ** bytesNeeded) / range) * range;
    const bytes = new Uint8Array(bytesNeeded);
    let value;

    do {
      crypto.getRandomValues(bytes);
      value = bytes.reduce((acc, x, n) => acc + x * 256 ** n, 0);
    } while (value >= cutoff);

    return min + (value % range);
  }
}

module.exports = SafeMathUtilities;

/**
 * Advanced Risk Manager for OGZPrime Trading System
 * @module RiskManager
 * @description Comprehensive risk management and position sizing engine
 */
const SafeMathUtilities = require('./SafeMathUtilities');

class RiskManager {
  /**
   * Constructor for Risk Manager
   * @param {Object} config - Configuration for risk management
   * @param {Object} dependencies - Injected dependencies for logging, market data, etc.
   */
  constructor(config = {}, dependencies = {}) {
    // Comprehensive configuration with sensible defaults
    this.config = {
      // Base risk parameters
      baseRiskPercent: config.baseRiskPercent || 0.02, // 2% default risk per trade
      maxRiskPercent: config.maxRiskPercent || 0.05, // 5% maximum risk
      minPositionSize: config.minPositionSize || 10, // $10 minimum trade size
      maxPositionSize: config.maxPositionSize || 1000, // $1000 maximum trade size

      // Advanced risk management parameters
      dynamicRiskScaling: config.dynamicRiskScaling || true,
      volatilityBuffer: config.volatilityBuffer || 0.005, // 0.5% additional buffer

      // Drawdown management
      maxDrawdownPercent: config.maxDrawdownPercent || 0.10, // 10% max drawdown
      recoveryMode: {
        enabled: config.recoveryMode?.enabled || true,
        reductionFactor: config.recoveryMode?.reductionFactor || 0.5 // Reduce risk by 50% in recovery
      },

      ...config
    };

    // Dependency injection
    this.logger = dependencies.logger || console;
    this.marketDataProvider = dependencies.marketDataProvider;

    // Risk state tracking
    this.riskState = {
      currentDrawdown: 0,
      consecutiveLosses: 0,
      inRecoveryMode: false,
      dailyStats: {
        trades: [],
        pnl: 0,
        maxLoss: 0
      }
    };
  }

  /**
   * Calculate dynamic position sizing
   * @param {Object} tradeContext - Comprehensive trade context
   * @returns {Object} Position sizing recommendation
   */
  calculatePositionSize(tradeContext) {
    const {
      balance,
      features,
      confidence,
      currentPrice,
      asset
    } = tradeContext;

    // Validate input
    if (!Number.isFinite(balance) || balance <= 0) {
      this.logger.warn('Invalid account balance for position sizing');
      return this.createPositionSizeResponse(0, 'Invalid balance');
    }

    // Base risk calculation
    let riskPercent = this.calculateDynamicRiskPercent(features, confidence);

    // Apply recovery mode adjustments
    if (this.riskState.inRecoveryMode) {
      riskPercent *= this.config.recoveryMode.reductionFactor;
    }

    // Calculate risk amount
    const riskAmount = SafeMathUtilities.safeDivide(
      balance * riskPercent, 
      currentPrice
    );

    // Position size validation
    const positionSize = this.validatePositionSize(
      riskAmount, 
      currentPrice, 
      balance
    );

    // Create comprehensive position sizing response
    return this.createPositionSizeResponse(
      positionSize, 
      'Position sized successfully',
      { riskPercent, riskAmount }
    );
  }

  /**
   * Calculate dynamic risk percentage
   * @param {Object} features - Trading features
   * @param {number} confidence - Trade confidence score
   * @returns {number} Dynamic risk percentage
   */
  calculateDynamicRiskPercent(features, confidence) {
    // Base risk calculation
    let dynamicRisk = this.config.baseRiskPercent;

    // Adjust risk based on market volatility
    if (features?.priceAction?.volatility) {
      const volatilityAdjustment = features.priceAction.volatility * this.config.volatilityBuffer;
      dynamicRisk += volatilityAdjustment;
    }

    // Confidence-based risk scaling
    dynamicRisk *= confidence;

    // Enforce risk boundaries
    return Math.max(
      Math.min(dynamicRisk, this.config.maxRiskPercent),
      this.config.baseRiskPercent
    );
  }

  /**
   * Validate and adjust position size
   * @param {number} calculatedSize - Calculated position size
   * @param {number} currentPrice - Current market price
   * @param {number} balance - Account balance
   * @returns {number} Validated position size
   */
  validatePositionSize(calculatedSize, currentPrice, balance) {
    const positionValue = calculatedSize * currentPrice;

    // Enforce minimum and maximum position sizes
    let validatedSize = Math.max(
      Math.min(
        calculatedSize, 
        this.config.maxPositionSize / currentPrice
      ),
      this.config.minPositionSize / currentPrice
    );

    // Ensure position doesn't exceed available balance
    if (positionValue > balance) {
      validatedSize = SafeMathUtilities.safeDivide(balance, currentPrice);
    }

    return validatedSize;
  }

  /**
   * Update risk state after trade execution
   * @param {Object} tradeResult - Detailed trade result
   */
  updateRiskState(tradeResult) {
    const { pnl, confidence } = tradeResult;

    // Update daily stats
    this.riskState.dailyStats.trades.push(tradeResult);
    this.riskState.dailyStats.pnl += pnl;
    this.riskState.dailyStats.maxLoss = Math.min(
      this.riskState.dailyStats.maxLoss, 
      pnl
    );

    // Track consecutive losses
    if (pnl < 0) {
      this.riskState.consecutiveLosses++;
    } else {
      this.riskState.consecutiveLosses = 0;
    }

    // Check for recovery mode
    this.checkRecoveryMode();
  }

  /**
   * Determine if trading should enter recovery mode
   * @private
   */
  checkRecoveryMode() {
    const { dailyStats, consecutiveLosses } = this.riskState;

    // Enter recovery mode conditions
    const shouldEnterRecoveryMode = 
      dailyStats.pnl < -this.config.maxDrawdownPercent ||
      consecutiveLosses >= 3;

    if (shouldEnterRecoveryMode && !this.riskState.inRecoveryMode) {
      this.logger.warn('Entering risk recovery mode');
      this.riskState.inRecoveryMode = true;
    }

    // Exit recovery mode conditions
    if (this.riskState.inRecoveryMode) {
      const recoveryConditions = 
        dailyStats.pnl > 0 && 
        consecutiveLosses === 0;

      if (recoveryConditions) {
        this.logger.info('Exiting risk recovery mode');
        this.riskState.inRecoveryMode = false;
      }
    }
  }

  /**
   * Create standardized position size response
   * @param {number} size - Position size
   * @param {string} message - Response message
   * @param {Object} [metadata] - Additional metadata
   * @returns {Object} Standardized response
   */
  createPositionSizeResponse(size, message, metadata = {}) {
    return {
      size,
      sizeUsd: size * (metadata.currentPrice || 0),
      allowed: size > 0,
      message,
      ...metadata
    };
  }

  /**
   * Generate comprehensive risk report
   * @returns {Object} Detailed risk report
   */
  generateRiskReport() {
    const { dailyStats, riskState } = this;

    return {
      currentDrawdown: this.riskState.currentDrawdown,
      inRecoveryMode: this.riskState.inRecoveryMode,
      dailyPerformance: {
        totalTrades: dailyStats.trades.length,
        profitableTrades: dailyStats.trades.filter(t => t.pnl > 0).length,
        totalPnl: dailyStats.pnl,
        maxLoss: dailyStats.maxLoss
      },
      riskParameters: this.config
    };
  }
}

