            ),
            layer2: Array(hiddenDim).fill().map(() => 
                Array(inputDim).fill().map(() => (Math.random() - 0.5) * 0.1)
            ),
            bias1: Array(hiddenDim).fill(() => Math.random() * 0.01),
            bias2: Array(inputDim).fill(() => Math.random() * 0.01)
        };
