/**
 * 1️⃣ BOLLINGER BANDS SYSTEM
 * Provides dynamic support/resistance and volatility context
 */
class BollingerBandsSystem {
  constructor(period = 20, stdDev = 2) {
    this.period = period;
    this.stdDev = stdDev;
    this.priceHistory = [];
    this.bandsHistory = [];
  }

  /**
   * Update with new price data
   */
  update(price) {
    this.priceHistory.push(price);
    if (this.priceHistory.length > this.period) {
      this.priceHistory.shift();
    }

    if (this.priceHistory.length >= this.period) {
      const bands = this.calculateBands();
      this.bandsHistory.push(bands);
      if (this.bandsHistory.length > 100) {
        this.bandsHistory.shift();
      }
      return bands;
    }
    return null;
  }

  /**
   * Calculate Bollinger Bands
   */
  calculateBands() {
    // Calculate Simple Moving Average (middle band)
    const sma = this.priceHistory.reduce((sum, price) => sum + price, 0) / this.period;

    // Calculate Standard Deviation
    const variance = this.priceHistory.reduce((sum, price) => {
      return sum + Math.pow(price - sma, 2);
    }, 0) / this.period;
    const stdDev = Math.sqrt(variance);

    // Calculate bands
    const upperBand = sma + (stdDev * this.stdDev);
    const lowerBand = sma - (stdDev * this.stdDev);

    // Calculate band width (volatility indicator)
    const bandwidth = (upperBand - lowerBand) / sma;

    // Calculate %B (position within bands)
    const currentPrice = this.priceHistory[this.priceHistory.length - 1];
    const percentB = (currentPrice - lowerBand) / (upperBand - lowerBand);

    return {
      upper: upperBand,
      middle: sma,
      lower: lowerBand,
      bandwidth: bandwidth,
      percentB: percentB,
      stdDev: stdDev,
      price: currentPrice,
      timestamp: Date.now()
    };
  }

  /**
   * Get trading signals from Bollinger Bands
   */
  getSignals(currentBands) {
    if (!currentBands) return null;

    const signals = {
      squeeze: false,
      breakout: null,
      reversal: null,
      trend: null
    };

    // Bollinger Squeeze detection (low volatility)
    if (currentBands.bandwidth < 0.05) { // Less than 5% bandwidth
      signals.squeeze = true;
      console.log('   🎯 BOLLINGER SQUEEZE DETECTED - Breakout imminent!');
    }

    // Band touch signals
    if (currentBands.percentB >= 1.0) {
      signals.reversal = 'sell';
      console.log('   📊 Price at UPPER BAND - Potential reversal down');
    } else if (currentBands.percentB <= 0.0) {
      signals.reversal = 'buy';
      console.log('   📊 Price at LOWER BAND - Potential reversal up');
    }

    // Breakout signals
    if (currentBands.percentB > 1.1) {
      signals.breakout = 'bullish';
      console.log('   🚀 BULLISH BREAKOUT above upper band!');
    } else if (currentBands.percentB < -0.1) {
      signals.breakout = 'bearish';
      console.log('   📉 BEARISH BREAKOUT below lower band!');
    }

    // Trend determination
    if (this.bandsHistory.length >= 5) {
      const recentBands = this.bandsHistory.slice(-5);
      const middleTrend = recentBands[4].middle - recentBands[0].middle;

      if (middleTrend > 0) {
        signals.trend = 'up';
      } else if (middleTrend < 0) {
        signals.trend = 'down';
      } else {
        signals.trend = 'sideways';
      }
    }

    return signals;
  }
}

/**
 * 2️⃣ VOLUME-WEIGHTED INDICATORS
 * VWAP and Volume-Weighted RSI for better entry/exit timing
 */
class VolumeWeightedIndicators {
  constructor() {
    this.vwapData = [];
    this.volumeRSIData = [];
    this.dailyReset = null;
  }

  /**
   * Update with price and volume data
   */
  update(price, volume) {
    const now = new Date();

    // Reset daily VWAP at market open
    if (this.shouldResetDaily(now)) {
      this.vwapData = [];
      this.dailyReset = now.toDateString();
    }

    // Add new data point
    const dataPoint = {
      price: price,
      volume: volume,
      typicalPrice: price, // For crypto, we use price as typical price
      timestamp: Date.now()
    };

    this.vwapData.push(dataPoint);

    // Calculate indicators
    const vwap = this.calculateVWAP();
    const volumeRSI = this.calculateVolumeWeightedRSI(price, volume);

    return {
      vwap: vwap,
      vwapDeviation: ((price - vwap) / vwap) * 100,
      volumeRSI: volumeRSI,
      cumulativeVolume: this.getCumulativeVolume(),
      averageVolume: this.getAverageVolume()
    };
  }

  /**
   * Calculate Volume Weighted Average Price (VWAP)
   */
  calculateVWAP() {
    if (this.vwapData.length === 0) return null;

    let sumPriceVolume = 0;
    let sumVolume = 0;

    for (const data of this.vwapData) {
      sumPriceVolume += data.price * data.volume;
      sumVolume += data.volume;
    }

    return sumVolume > 0 ? sumPriceVolume / sumVolume : null;
  }

  /**
   * Calculate Volume-Weighted RSI
   */
  calculateVolumeWeightedRSI(price, volume, period = 14) {
    // Store price changes with volume
    if (this.volumeRSIData.length > 0) {
      const lastData = this.volumeRSIData[this.volumeRSIData.length - 1];
      const change = price - lastData.price;

      this.volumeRSIData.push({
        price: price,
        volume: volume,
        change: change,
        weightedChange: change * volume
      });
    } else {
      this.volumeRSIData.push({
        price: price,
        volume: volume,
        change: 0,
        weightedChange: 0
      });
    }

    // Keep only needed periods
    if (this.volumeRSIData.length > period + 1) {
      this.volumeRSIData.shift();
    }

    if (this.volumeRSIData.length < period) return 50; // Default RSI

    // Calculate volume-weighted gains and losses
    let weightedGains = 0;
    let weightedLosses = 0;
    let totalVolume = 0;

    for (let i = 1; i < this.volumeRSIData.length; i++) {
      const data = this.volumeRSIData[i];
      totalVolume += data.volume;

      if (data.change > 0) {
        weightedGains += data.weightedChange;
      } else {
        weightedLosses += Math.abs(data.weightedChange);
      }
    }

    // Calculate volume-weighted RSI
    if (totalVolume === 0 || weightedLosses === 0) return 100;

    const rs = weightedGains / weightedLosses;
    return 100 - (100 / (1 + rs));
  }

  /**
   * Get trading signals from volume-weighted indicators
   */
  getSignals(indicators, price) {
    const signals = {
      vwapCross: null,
      volumeConfirmation: false,
      divergence: null
    };

    if (!indicators.vwap) return signals;

    // VWAP crossover signals
    if (price > indicators.vwap && indicators.vwapDeviation > 0.5) {
      signals.vwapCross = 'bullish';
      console.log('   📈 Price ABOVE VWAP - Bullish bias');
    } else if (price < indicators.vwap && indicators.vwapDeviation < -0.5) {
      signals.vwapCross = 'bearish';
      console.log('   📉 Price BELOW VWAP - Bearish bias');
    }

    // Volume confirmation
    const avgVolume = indicators.averageVolume;
    const currentVolume = this.vwapData[this.vwapData.length - 1]?.volume || 0;

    if (currentVolume > avgVolume * 1.5) {
      signals.volumeConfirmation = true;
      console.log('   ✅ HIGH VOLUME confirmation!');
    }

    // RSI divergence detection
    if (indicators.volumeRSI > 70 && price < indicators.vwap) {
      signals.divergence = 'bearish';
      console.log('   ⚠️ BEARISH DIVERGENCE detected!');
    } else if (indicators.volumeRSI < 30 && price > indicators.vwap) {
      signals.divergence = 'bullish';
      console.log('   ⚠️ BULLISH DIVERGENCE detected!');
    }

    return signals;
  }

  shouldResetDaily(now) {
    return !this.dailyReset || this.dailyReset !== now.toDateString();
  }

  getCumulativeVolume() {
    return this.vwapData.reduce((sum, data) => sum + data.volume, 0);
  }

  getAverageVolume() {
    if (this.vwapData.length === 0) return 0;
    return this.getCumulativeVolume() / this.vwapData.length;
  }
}

/**
 * 3️⃣ ENHANCED MULTI-TIMEFRAME ANALYSIS
 * Comprehensive MTF system for signal confirmation
 */
class MultiTimeframeAnalysisSystem {
  constructor() {
    this.timeframes = {
      '1m': { candles: [], indicators: {} },
      '5m': { candles: [], indicators: {} },
      '15m': { candles: [], indicators: {} },
      '1h': { candles: [], indicators: {} },
      '4h': { candles: [], indicators: {} }
    };

    this.aggregationRules = {
      '5m': 5,    // 5 x 1m candles
      '15m': 15,  // 15 x 1m candles
      '1h': 60,   // 60 x 1m candles
      '4h': 240   // 240 x 1m candles
    };

    this.lastCandle = {};
  }

  /**
   * Update all timeframes with new 1-minute data
   */
  update(price, volume) {
    const now = Date.now();
    const currentMinute = Math.floor(now / 60000) * 60000;

    // Update or create 1-minute candle
    if (!this.lastCandle['1m'] || this.lastCandle['1m'].time !== currentMinute) {
      // Close previous candle and start new one
      if (this.lastCandle['1m']) {
        this.addCandle('1m', this.lastCandle['1m']);
        this.aggregateHigherTimeframes();
      }

      this.lastCandle['1m'] = {
        time: currentMinute,
        open: price,
        high: price,
        low: price,
        close: price,
        volume: volume
      };
    } else {
      // Update current candle
      const candle = this.lastCandle['1m'];
      candle.high = Math.max(candle.high, price);
      candle.low = Math.min(candle.low, price);
      candle.close = price;
      candle.volume += volume;
    }

    // Calculate indicators for all timeframes
    return this.calculateAllIndicators();
  }

  /**
   * Add completed candle to timeframe
   */
  addCandle(timeframe, candle) {
    this.timeframes[timeframe].candles.push(candle);

    // Keep only last 200 candles
    if (this.timeframes[timeframe].candles.length > 200) {
      this.timeframes[timeframe].candles.shift();
    }
  }

  /**
   * Aggregate 1m candles into higher timeframes
   */
  aggregateHigherTimeframes() {
    const oneMinCandles = this.timeframes['1m'].candles;
    if (oneMinCandles.length === 0) return;

    for (const [timeframe, multiplier] of Object.entries(this.aggregationRules)) {
      const tfData = this.timeframes[timeframe];
      const lastCandle = tfData.candles[tfData.candles.length - 1];
      const currentPeriod = Math.floor(oneMinCandles[oneMinCandles.length - 1].time / (multiplier * 60000)) * (multiplier * 60000);

      // Check if we need to start a new candle
      if (!lastCandle || lastCandle.time !== currentPeriod) {
        // Aggregate the last 'multiplier' 1m candles
        const relevantCandles = oneMinCandles.slice(-multiplier);

        if (relevantCandles.length > 0) {
          const aggregatedCandle = {
            time: currentPeriod,
            open: relevantCandles[0].open,
            high: Math.max(...relevantCandles.map(c => c.high)),
            low: Math.min(...relevantCandles.map(c => c.low)),
            close: relevantCandles[relevantCandles.length - 1].close,
            volume: relevantCandles.reduce((sum, c) => sum + c.volume, 0)
          };

          this.addCandle(timeframe, aggregatedCandle);
        }
      }
    }
  }

  /**
   * Calculate indicators for all timeframes
   */
  calculateAllIndicators() {
    const analysis = {};

    for (const [timeframe, data] of Object.entries(this.timeframes)) {
      const candles = data.candles;
      if (candles.length < 20) continue;

      const indicators = {
        sma20: this.calculateSMA(candles, 20),
        sma50: this.calculateSMA(candles, 50),
        ema12: this.calculateEMA(candles, 12),
        ema26: this.calculateEMA(candles, 26),
        rsi: this.calculateRSI(candles, 14),
        trend: this.determineTrend(candles),
        momentum: this.calculateMomentum(candles),
        support: this.findSupport(candles),
        resistance: this.findResistance(candles)
      };

      // Store indicators
      this.timeframes[timeframe].indicators = indicators;

      // Add to analysis
      analysis[timeframe] = {
        ...indicators,
        lastCandle: candles[candles.length - 1]
      };
    }

    // Calculate confluence score
    analysis.confluence = this.calculateConfluence(analysis);

    return analysis;
  }

  /**
   * Calculate confluence across timeframes
   */
  calculateConfluence(analysis) {
    let bullishScore = 0;
    let bearishScore = 0;
    const weights = { '1m': 0.1, '5m': 0.2, '15m': 0.3, '1h': 0.3, '4h': 0.1 };

    for (const [timeframe, data] of Object.entries(analysis)) {
      if (!data.trend || !weights[timeframe]) continue;

      const weight = weights[timeframe];

      // Trend alignment
      if (data.trend === 'up') bullishScore += weight * 2;
      else if (data.trend === 'down') bearishScore += weight * 2;

      // RSI signals
      if (data.rsi < 30) bullishScore += weight;
      else if (data.rsi > 70) bearishScore += weight;

      // Moving average signals
      if (data.lastCandle && data.sma20) {
        if (data.lastCandle.close > data.sma20) bullishScore += weight;
        else bearishScore += weight;
      }

      // Momentum
      if (data.momentum > 0) bullishScore += weight * 0.5;
      else if (data.momentum < 0) bearishScore += weight * 0.5;
    }

    const totalScore = bullishScore + bearishScore;

    return {
      bullishScore: bullishScore,
      bearishScore: bearishScore,
      totalScore: totalScore,
      bullishPercent: totalScore > 0 ? (bullishScore / totalScore) * 100 : 50,
      bearishPercent: totalScore > 0 ? (bearishScore / totalScore) * 100 : 50,
      signal: bullishScore > bearishScore * 1.2 ? 'buy' : 
              bearishScore > bullishScore * 1.2 ? 'sell' : 'neutral',
      strength: Math.abs(bullishScore - bearishScore) / totalScore
    };
  }

  // Technical indicator calculations
  calculateSMA(candles, period) {
    if (candles.length < period) return null;
    const sum = candles.slice(-period).reduce((acc, c) => acc + c.close, 0);
    return sum / period;
  }

  calculateEMA(candles, period) {
    if (candles.length < period) return null;
    const multiplier = 2 / (period + 1);
    let ema = this.calculateSMA(candles.slice(0, period), period);

    for (let i = period; i < candles.length; i++) {
      ema = (candles[i].close * multiplier) + (ema * (1 - multiplier));
    }

    return ema;
  }

  calculateRSI(candles, period = 14) {
    if (candles.length < period + 1) return 50;

    let gains = 0;
    let losses = 0;

    for (let i = candles.length - period; i < candles.length; i++) {
      const change = candles[i].close - candles[i - 1].close;
      if (change > 0) gains += change;
      else losses += Math.abs(change);
    }

    const avgGain = gains / period;
    const avgLoss = losses / period;

    if (avgLoss === 0) return 100;
    const rs = avgGain / avgLoss;
    return 100 - (100 / (1 + rs));
  }

  calculateMomentum(candles, period = 10) {
    if (candles.length < period) return 0;
    const oldPrice = candles[candles.length - period].close;
    const currentPrice = candles[candles.length - 1].close;
    return ((currentPrice - oldPrice) / oldPrice) * 100;
  }

  determineTrend(candles) {
    if (candles.length < 20) return 'neutral';

    const sma20 = this.calculateSMA(candles, 20);
    const currentPrice = candles[candles.length - 1].close;
    const oldSMA = this.calculateSMA(candles.slice(0, -5), 20);

    if (currentPrice > sma20 && sma20 > oldSMA) return 'up';
    if (currentPrice < sma20 && sma20 < oldSMA) return 'down';
    return 'sideways';
  }

  findSupport(candles, lookback = 50) {
    const relevantCandles = candles.slice(-Math.min(lookback, candles.length));
    return Math.min(...relevantCandles.map(c => c.low));
  }

  findResistance(candles, lookback = 50) {
    const relevantCandles = candles.slice(-Math.min(lookback, candles.length));
    return Math.max(...relevantCandles.map(c => c.high));
  }
}

